  "content": "[Provider Portal]\r\n|\r\n\r\n\\\u002B\r\n\r\n\\\u002B\r\n\\\u002B\r\n\r\n|\r\n\r\n[My Profile]\r\n|\r\n\r\n|\r\n[HR \u0026 Admin]\r\n|\r\n\r\n|\r\n\r\n[Clinical]\r\n\r\n|\r\n\r\n\\\u002B -- \u003E Edit Bio\r\n\\\u002B -- \u003E Request Documents \u002B -- \u003E Submit Tickets\r\n\r\n\\\u002B -- \u003E Edit Specialties \u002B -- \u003E Update Bank Details \u002B -- \u003E Crisis Protocol\r\n\r\n\\\u002B -- \u003E Availability\r\n\r\n\\\u002B -- \u003E HR Ticket Escalation\u002B -- \u003E EHR Notes\r\n\r\n\u003C!-- PageBreak --\u003E",
